function isIgnoredPath(file, patterns) {
  for (var i = 0; i < patterns.length; i++) {
    var p = patterns[i];
    if (p.slice(-3) === '/**') {
      if (file.indexOf(p.slice(0, -3) + '/') === 0) return true;
    } else if (file === p) {
      return true;
    }
  }
