function pathsIgnoreFromWorkflow(yml) {
  var patterns = [];
  if (!yml) return patterns;
  var lines = yml.split(/\r?\n/);
  var inIgnore = false;
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    var trimmed = line.trim();
    if (!inIgnore) {
      if (/^paths-ignore:\s*$/.test(trimmed)) { inIgnore = true; }
      continue;
    }
    // entries are '- 'pattern'' one indent level deeper
    var m = /^-\s*'([^']+)'\s*$/.exec(trimmed);
    if (m) { patterns.push(m[1]); continue; }
    // allow double quotes too
    var m2 = /^-\s*"([^"]+)"\s*$/.exec(trimmed);
    if (m2) { patterns.push(m2[1]); continue; }
    // any non-list line ends the block
    if (trimmed !== '' && trimmed.charAt(0) !== '#') break;
  }
  return patterns;
}
