        assert.deepEqual(guard().pathsIgnoreFromWorkflow('name: x\non:\n  push:\n'), []);
    });

    test('the guard does not carry a hardcoded copy of the ignore list', function () {
        var src = file_read({ path: 'ci/release_kicker_guard.cjs' });
