import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const RELEASE_WF = '.github/workflows/agent-pack-release.yml';
const WORKFLOW_NAME = 'agent-pack-release.yml';
const RELEASE_TAG_PREFIX = 'agents-rel-';

function sh(cmd, args) {
  return execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
}
function gh(args) { return sh('gh', args); }

// 1. main HEAD
const mainHead = sh('git', ['rev-parse', 'origin/main']);
// 2. latest release tag + its commit
let releaseCommit = '';
let tag = '';
try {
  tag = sh('git', ['tag', '--list', RELEASE_TAG_PREFIX + '*', '--sort=-creatordate']).split('\n')[0].trim();
  if (tag) releaseCommit = sh('git', ['rev-list', '-n', '1', tag]);
} catch { }

// 3. changed files since tag
let changedFiles = null;
if (releaseCommit) {
  const out = sh('git', ['diff', '--name-only', releaseCommit + '...' + mainHead]);
  changedFiles = out ? out.split('\n').map(s => s.trim()).filter(Boolean) : [];
}

// 4. pending/in-progress release runs
const runsJson = gh(['run', 'list', '--workflow', WORKFLOW_NAME, '--json', 'status']);
const activeReleaseRuns = JSON.parse(runsJson).filter(r => r.status === 'queued' || r.status === 'in_progress').length;

// 5. decide via the guard
const yml = readFileSync(RELEASE_WF, 'utf8');
const ignored = pathsIgnoreFromWorkflow(yml);
const decision = decideKick({ mainHead, releaseCommit, changedFiles, activeReleaseRuns, ignored });

